#if defined(_MSC_VER)
#pragma warning(push, 0)
#endif
#include "manifold_kernel.cpp"   // generated by slangc into the build tree
#if defined(_MSC_VER)
#pragma warning(pop)
#endif

namespace ohao::caustics {

namespace {

using F4 = Vector<float, 4>;

F4 f4(float x, float y, float z, float w) {
    F4 v{};
    v.x = x;
    v.y = y;
    v.z = z;
    v.w = w;
    return v;
}
F4 f4(const V3& v, float w = 0.0f) { return f4(v[0], v[1], v[2], w); }

struct Io {
    F4 rows[20]{};
};

Io base(float op, const Tri* tri, const V3* p, const V3* L) {
    Io io;
    io.rows[0] = f4(op, 0, 0, 0);
    if (tri) {
        io.rows[1] = f4(tri->p0, tri->c[0]);
        io.rows[2] = f4(tri->e1, tri->c[1]);
        io.rows[3] = f4(tri->e2, tri->c[2]);
        io.rows[4] = f4(tri->n0);
        io.rows[5] = f4(tri->a1);
        io.rows[6] = f4(tri->a2);
    }
    if (p) io.rows[7] = f4(*p);
    if (L) io.rows[8] = f4(*L);
    return io;
}

void runItem(Io& io) {
    GlobalParams_0 globals{};
    globals.io_0.data = io.rows;
    globals.io_0.count = 20;
    ComputeVaryingInput range{};
    range.startGroupID = {0, 0, 0};
    range.endGroupID = {1, 1, 1};
    ::run(&range, nullptr, &globals);
}

} // namespace

MapResult manifoldMap(const Tri& tri, const V3& p, const V3& L, V2 uv) {
    Io io = base(0, &tri, &p, &L);
    io.rows[9] = f4(uv[0], uv[1], 0, 0);
    runItem(io);
    MapResult r;
    r.ok = io.rows[13].z != 0.0f;
    r.sigma = {io.rows[13].x, io.rows[13].y};
    r.du = {io.rows[14].x, io.rows[14].y};
    r.dv = {io.rows[14].z, io.rows[14].w};
    r.y = {io.rows[15].x, io.rows[15].y, io.rows[15].z};
    r.n = {io.rows[16].x, io.rows[16].y, io.rows[16].z};
    return r;
}

bool manifoldSolve(const Tri& tri, const V3& p, const V3& L, V2 target, float tol, V2& uv) {
    Io io = base(1, &tri, &p, &L);
    io.rows[0].y = tol;
    io.rows[9] = f4(target[0], target[1], 0, 0);
    runItem(io);
    uv = {io.rows[13].x, io.rows[13].y};
    return io.rows[13].z != 0.0f;
}

V2 manifoldDrawSlope(V2 alphas, float slope2, float minSlope2, const V3& u, float& density) {
    Io io = base(2, nullptr, nullptr, nullptr);
    io.rows[0].z = slope2;
    io.rows[11].x = minSlope2;
    io.rows[9] = f4(0, 0, alphas[0], alphas[1]);
    io.rows[10] = f4(u);
    runItem(io);
    density = io.rows[13].z;
    return {io.rows[13].x, io.rows[13].y};
}

float manifoldSlopeDensity(V2 alphas, float slope2, float minSlope2, V2 sigma) {
    Io io = base(3, nullptr, nullptr, nullptr);
    io.rows[0].z = slope2;
    io.rows[11].x = minSlope2;
    io.rows[9] = f4(sigma[0], sigma[1], alphas[0], alphas[1]);
    runItem(io);
    return io.rows[13].x;
}

bool manifoldTriangleTest(const Tri& tri, const V3& p, const V3& L, V2 sigma) {
    Io io = base(5, &tri, &p, &L);
    io.rows[9] = f4(sigma[0], sigma[1], 0, 0);
    runItem(io);
    return io.rows[13].x != 0.0f;
}

bool manifoldDiscTest(const V3& boxMin, const V3& boxMax, const V3& axis, float halfAngle, const V3& c, V2 sigma,
                      const V3& p, const V3& L) {
    Tri tri{};
    tri.c = c;
    Io io = base(6, &tri, &p, &L);
    io.rows[9] = f4(sigma[0], sigma[1], 0, 0);
    io.rows[10] = f4(boxMin);
    io.rows[11] = f4(boxMax);
    io.rows[12] = f4(axis, halfAngle);
    runItem(io);
    return io.rows[13].x != 0.0f;
}

bool manifoldConeTest(const V3& boxMin, const V3& boxMax, const V3& axis, float halfAngle, const V3& p, const V3& L,
                      float thetaSigma) {
    Io io = base(4, nullptr, &p, &L);
    io.rows[0].w = thetaSigma;
    io.rows[10] = f4(boxMin);
    io.rows[11] = f4(boxMax);
    io.rows[12] = f4(axis, halfAngle);
    runItem(io);
    return io.rows[13].x != 0.0f;
}

} // namespace ohao::caustics
